const item = $input.first();
const headers = item.json.headers || {};
const providedSecret = headers['x-trip-ingest-secret'];
const expectedSecret = $env.TRIP_INGEST_SHARED_SECRET;
const secretValid = Boolean(expectedSecret) && providedSecret === expectedSecret;

let rawBody = '';
if (item.binary && item.binary.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  rawBody = buffer.toString('utf-8');
}

const fromMatch = rawBody.match(/^From:\s*(.+)$/im);
const subjectMatch = rawBody.match(/^Subject:\s*(.+)$/im);
const topContentTypeMatch = rawBody.match(/^Content-Type:\s*([^\r\n]+(?:\r?\n[ \t][^\r\n]+)*)/im);

function decodeQuotedPrintable(str) {
  return str.replace(/=\r?\n/g, '').replace(/=([0-9A-Fa-f]{2})/g, function (_, hex) {
    return String.fromCharCode(parseInt(hex, 16));
  });
}

function parseHeaders(block) {
  const result = {};
  const lines = block.split(/\r?\n/);
  let lastKey = null;
  for (const line of lines) {
    if (/^[ \t]/.test(line) && lastKey) {
      result[lastKey] += ' ' + line.trim();
      continue;
    }
    const m = line.match(/^([^:]+):\s*(.*)$/);
    if (m) {
      lastKey = m[1].toLowerCase();
      result[lastKey] = m[2];
    }
  }
  return result;
}

function getBoundary(contentType) {
  const m = contentType && contentType.match(/boundary="?([^";]+)"?/i);
  return m ? m[1] : null;
}

function splitParts(body, boundary) {
  const delim = '--' + boundary;
  const pieces = body.split(delim);
  return pieces.slice(1, -1).map(function (p) {
    return p.replace(/^\r?\n/, '');
  });
}

function splitHeaderBody(part) {
  const idx = part.search(/\r?\n\r?\n/);
  if (idx === -1) return { headerBlock: part, bodyBlock: '' };
  const sepMatch = part.slice(idx).match(/^\r?\n\r?\n/);
  return {
    headerBlock: part.slice(0, idx),
    bodyBlock: part.slice(idx + sepMatch[0].length),
  };
}

function walkMime(headerBlock, bodyBlock, collector) {
  const partHeaders = parseHeaders(headerBlock);
  const contentType = partHeaders['content-type'] || 'text/plain';
  const boundary = getBoundary(contentType);
  if (boundary) {
    const parts = splitParts(bodyBlock, boundary);
    for (const part of parts) {
      const split = splitHeaderBody(part);
      walkMime(split.headerBlock, split.bodyBlock, collector);
    }
    return;
  }
  const encoding = (partHeaders['content-transfer-encoding'] || '').toLowerCase();
  const disposition = partHeaders['content-disposition'] || '';
  const isAttachment = /attachment/i.test(disposition) || /^application\//i.test(contentType);
  if (isAttachment) {
    const filenameMatch = disposition.match(/filename="?([^";]+)"?/i) || contentType.match(/name="?([^";]+)"?/i);
    collector.attachments.push({
      contentType: contentType,
      filename: filenameMatch ? filenameMatch[1] : 'attachment',
      encoding: encoding,
      raw: bodyBlock,
    });
    return;
  }
  let decoded = bodyBlock;
  if (encoding === 'quoted-printable') {
    decoded = decodeQuotedPrintable(bodyBlock);
  } else if (encoding === 'base64') {
    decoded = Buffer.from(bodyBlock.replace(/\r?\n/g, ''), 'base64').toString('utf-8');
  }
  if (/^text\/plain/i.test(contentType) && !collector.textPlain) {
    collector.textPlain = decoded;
  } else if (/^text\/html/i.test(contentType) && !collector.textHtml) {
    collector.textHtml = decoded;
  }
}

const collector = { textPlain: null, textHtml: null, attachments: [] };

if (topContentTypeMatch && /multipart\//i.test(topContentTypeMatch[1])) {
  const split = splitHeaderBody(rawBody);
  walkMime(split.headerBlock, split.bodyBlock, collector);
} else {
  const split = splitHeaderBody(rawBody);
  collector.textPlain = split.bodyBlock || rawBody;
}

const bodyText = collector.textPlain || collector.textHtml || '';
const pdfAttachment = collector.attachments.find(function (a) {
  return /pdf/i.test(a.contentType) || /\.pdf$/i.test(a.filename);
});

const outputItem = {
  json: {
    secretValid: secretValid,
    envelopeFrom: headers['x-envelope-from'] || null,
    mimeFrom: fromMatch ? fromMatch[1].trim() : null,
    subject: subjectMatch ? subjectMatch[1].trim() : null,
    bodyPreview: bodyText.slice(0, 3000),
    hasPdfAttachment: Boolean(pdfAttachment),
  },
};

if (pdfAttachment) {
  const pdfBuffer = Buffer.from(pdfAttachment.raw.replace(/\r?\n/g, ''), 'base64');
  outputItem.binary = {
    attachment: await this.helpers.prepareBinaryData(pdfBuffer, pdfAttachment.filename, 'application/pdf'),
  };
}

return [outputItem];

const item = $('Code in JavaScript').item.json;
const pdfExtraction = $input.first().json || {};
const pdfText = (pdfExtraction.text || pdfExtraction.data || '').toString().slice(0, 7000);
const emailText =
  'From: ' +
  (item.mimeFrom || '') +
  '\nSubject: ' +
  (item.subject || '') +
  '\n\n' +
  (item.bodyPreview || '') +
  (pdfText ? '\n\n--- Attached PDF itinerary (text extract) ---\n' + pdfText : '');
const systemPrompt =
  'You extract structured travel booking data from an email, optionally with an attached PDF itinerary appended after it. Return null for any field not present in the source - never invent data.\n\nbooking_type classification, in order of precedence:\n- flight: has an airline name, a flight number, or a departure/arrival airport.\n- lodging: has a hotel, resort, Airbnb, or check-in/check-out date - even if it also mentions a city or airport nearby.\n- cruise: a cruise line booking (Royal Caribbean, Carnival, etc), usually multi-day with several ports of call.\n- rental_car: a car rental agency (Hertz, Avis, Enterprise, etc).\n- transit: ground or short-hop water transport between cities that is NOT a flight, rental car, or cruise - train, bus, ferry.\n- restaurant: a dining reservation.\n- activity: a tour, ticket, or event booking.\n- general: anything else, including newsletters and emails with no booking details.\n\nIATA or station codes go in the _code fields; the human-readable name goes in the _name fields. For lodging, destination_name/destination_code refer to the hotel\'s city, not the hotel itself - the hotel name goes in provider_name. Dates must be ISO-8601 (YYYY-MM-DDTHH:mm:ss) when a date is present in the source; if only a date with no time is given, use T00:00:00. If a year is not stated, infer it from context (e.g. a date later than any date already mentioned) rather than defaulting to the current year.\n\nFor cruise bookings: start_datetime/end_datetime are the embarkation/disembarkation date and time. Populate the stops array with every port of call in visit order, including embarkation and disembarkation as the first and last entries - skip pure sea/cruising days that have no port. Each stop needs a name and a date (YYYY-MM-DD). For all other booking types, leave stops empty.';
const schema = {
  type: 'object',
  properties: {
    booking_type: { type: 'string', enum: ['flight', 'lodging', 'rental_car', 'transit', 'cruise', 'restaurant', 'activity', 'general'] },
    confirmation_code: { type: ['string', 'null'] },
    provider_name: { type: ['string', 'null'] },
    start_datetime: { type: ['string', 'null'] },
    end_datetime: { type: ['string', 'null'] },
    origin_name: { type: ['string', 'null'] },
    origin_code: { type: ['string', 'null'] },
    destination_name: { type: ['string', 'null'] },
    destination_code: { type: ['string', 'null'] },
    stops: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          date: { type: ['string', 'null'] },
        },
        required: ['name'],
      },
    },
    notes: { type: ['string', 'null'] },
  },
  required: ['booking_type'],
};
const exampleEmail =
  'From: jane@example.com\nSubject: Your Hilton Reservation - Confirmation HH1234\n\nThank you for booking the Hilton Garden Inn Austin Downtown.\n\nConfirmation Number: HH1234\nCheck-in: June 3, 2027\nCheck-out: June 5, 2027';
const exampleAnswer = JSON.stringify({
  booking_type: 'lodging',
  confirmation_code: 'HH1234',
  provider_name: 'Hilton Garden Inn Austin Downtown',
  start_datetime: '2027-06-03T00:00:00',
  end_datetime: '2027-06-05T00:00:00',
  origin_name: null,
  origin_code: null,
  destination_name: 'Austin',
  destination_code: null,
  stops: [],
  notes: null,
});
const cruiseExample =
  'From: agent@example.com\nSubject: Your Cruise Confirmation - ABC999\n\n--- Attached PDF itinerary (text extract) ---\nCruise Confirmation\nConfirmation: ABC999\nRoyal Caribbean\nEmbark: May 1, 2028\nDisembark: May 5, 2028\nDay 1: Miami, Florida - May 1, 2028 | Depart 06:00 PM\nDay 2: Cruising - May 2, 2028\nDay 3: Nassau, Bahamas - May 3, 2028 | 08:00 AM To 05:00 PM\nDay 4: CocoCay, Bahamas - May 4, 2028 | 08:00 AM To 04:00 PM\nDay 5: Miami, Florida - May 5, 2028 | Arrive 06:00 AM';
const cruiseAnswer = JSON.stringify({
  booking_type: 'cruise',
  confirmation_code: 'ABC999',
  provider_name: 'Royal Caribbean',
  start_datetime: '2028-05-01T18:00:00',
  end_datetime: '2028-05-05T06:00:00',
  origin_name: null,
  origin_code: null,
  destination_name: null,
  destination_code: null,
  stops: [
    { name: 'Miami, Florida', date: '2028-05-01' },
    { name: 'Nassau, Bahamas', date: '2028-05-03' },
    { name: 'CocoCay, Bahamas', date: '2028-05-04' },
    { name: 'Miami, Florida', date: '2028-05-05' },
  ],
  notes: null,
});
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama.ai.svc.cluster.local:11434/api/chat',
  body: {
    model: 'mistral:latest',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: exampleEmail },
      { role: 'assistant', content: exampleAnswer },
      { role: 'user', content: cruiseExample },
      { role: 'assistant', content: cruiseAnswer },
      { role: 'user', content: emailText },
    ],
    stream: false,
    format: schema,
  },
  json: true,
  timeout: 90000,
});
let extracted;
try {
  extracted = JSON.parse(response.message.content);
} catch (e) {
  extracted = { booking_type: 'general', parse_error: String(e) };
}
return [{ json: { ...item, extracted } }];

const item = $input.first().json;
const ex = item.extracted || {};
const helpers = this.helpers;

const TREK_URL = 'http://trek.household.svc.cluster.local:3000/mcp';
const TREK_TOKEN = $env.TREK_API_TOKEN;

function baseHeaders(sessionId) {
  const h = {
    'Authorization': 'Bearer ' + TREK_TOKEN,
    'Content-Type': 'application/json',
    'Accept': 'application/json, text/event-stream',
    'X-Forwarded-Proto': 'https',
    'Host': 'trip.sysinfra.pro',
  };
  if (sessionId) h['Mcp-Session-Id'] = sessionId;
  return h;
}

function parseMcpBody(bodyText) {
  const match = bodyText.match(/data:\s*(\{[\s\S]*\})/);
  const jsonText = match ? match[1] : bodyText;
  return JSON.parse(jsonText);
}

async function mcpRpc(sessionId, method, params) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: TREK_URL,
    headers: baseHeaders(sessionId),
    body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: method, params: params || {} }),
    returnFullResponse: true,
  });
  return { parsed: parseMcpBody(String(res.body)), headers: res.headers };
}

async function mcpTool(sessionId, toolName, args) {
  const r = await mcpRpc(sessionId, 'tools/call', { name: toolName, arguments: args || {} });
  if (r.parsed.error) {
    throw new Error('Trek MCP error calling ' + toolName + ': ' + JSON.stringify(r.parsed.error));
  }
  const content = (r.parsed.result && r.parsed.result.content) || [];
  const textPart = content[content.length - 1];
  const raw = textPart ? textPart.text : '{}';
  try {
    return JSON.parse(raw);
  } catch (e) {
    return { raw: raw };
  }
}

function toDate(s) {
  return s ? new Date(s) : null;
}

const initRes = await mcpRpc(null, 'initialize', {
  protocolVersion: '2024-11-05',
  capabilities: {},
  clientInfo: { name: 'n8n-trip-ingest', version: '1.0' },
});
const sessionId = initRes.headers['mcp-session-id'] || initRes.headers['Mcp-Session-Id'];

const tripsData = await mcpTool(sessionId, 'list_trips', {});
const trips = tripsData.trips || [];

const startDt = toDate(ex.start_datetime);
const endDt = toDate(ex.end_datetime) || startDt;

let matchedTrip = null;
if (startDt) {
  const windowMs = 3 * 24 * 60 * 60 * 1000;
  for (const t of trips) {
    const tStart = new Date(t.start_date + 'T00:00:00');
    const tEnd = new Date(t.end_date + 'T23:59:59');
    if (startDt.getTime() >= tStart.getTime() - windowMs && startDt.getTime() <= tEnd.getTime() + windowMs) {
      matchedTrip = t;
      break;
    }
  }
}

let tripId;
let createdNewTrip = false;
if (matchedTrip) {
  tripId = matchedTrip.id;
} else {
  const destName = ex.destination_name || ex.destination_code || ex.provider_name || 'Trip';
  const startDateStr = startDt ? startDt.toISOString().slice(0, 10) : null;
  const endDateStr = endDt ? endDt.toISOString().slice(0, 10) : startDateStr;
  const createArgs = { title: 'Trip to ' + destName };
  if (startDateStr) createArgs.start_date = startDateStr;
  if (endDateStr) createArgs.end_date = endDateStr;
  const created = await mcpTool(sessionId, 'create_trip', createArgs);
  tripId = created.trip ? created.trip.id : created.id;
  createdNewTrip = true;
}

const summary = await mcpTool(sessionId, 'get_trip_summary', { tripId: tripId });
const days = summary.days || [];

function findDayId(dateStr) {
  if (!dateStr) return null;
  const day = days.find(function (d) {
    return d.date === dateStr;
  });
  return day ? day.id : null;
}

const startDateOnly = startDt ? startDt.toISOString().slice(0, 10) : null;
const endDateOnly = endDt ? endDt.toISOString().slice(0, 10) : startDateOnly;
const startDayId = findDayId(startDateOnly);
const endDayId = findDayId(endDateOnly) || startDayId;

const existingReservations = summary.reservations || [];
const existingAccommodations = summary.accommodations || [];

const isLodging = ex.booking_type === 'lodging';

const isDuplicate = Boolean(
  ex.confirmation_code &&
    (isLodging
      ? existingAccommodations.some(function (a) {
          return a.confirmation === ex.confirmation_code;
        })
      : existingReservations.some(function (r) {
          return r.confirmation_number === ex.confirmation_code;
        }))
);

let createdBooking = null;
let placeSearchNote = null;

if (!isDuplicate) {
  if (ex.booking_type === 'flight' || ex.booking_type === 'transit' || ex.booking_type === 'cruise') {
    const transportTypeMap = { flight: 'flight', transit: 'train', cruise: 'cruise' };
    const transportType = transportTypeMap[ex.booking_type];
    const args = {
      tripId: tripId,
      type: transportType,
      title: (ex.provider_name || transportType) + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
    };
    if (startDayId) args.start_day_id = startDayId;
    if (endDayId) args.end_day_id = endDayId;
    if (ex.start_datetime) args.reservation_time = ex.start_datetime;
    if (ex.end_datetime) args.reservation_end_time = ex.end_datetime;
    if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
    const stops = (ex.stops || []).filter(function (s) {
      return s && s.name && !/^cruising$|^at sea$|^day at sea$|^sea day$/i.test(s.name.trim());
    });
    if (stops.length > 1) {
      args.endpoints = stops.map(function (s, i) {
        return {
          role: i === 0 ? 'from' : i === stops.length - 1 ? 'to' : 'stop',
          sequence: i,
          name: s.name,
          local_date: s.date || undefined,
        };
      });
    }
    createdBooking = await mcpTool(sessionId, 'create_transport', args);
  } else if (isLodging && startDayId && endDayId) {
    const searchQuery = [ex.provider_name, ex.destination_name || ex.destination_code]
      .filter(Boolean)
      .join(' ');
    let placeId = null;
    if (searchQuery) {
      const searchResult = await mcpTool(sessionId, 'search_place', { query: searchQuery });
      const places = searchResult.places || [];
      const best = places[0];
      if (best) {
        const placeArgs = {
          tripId: tripId,
          name: best.name || ex.provider_name || 'Hotel',
        };
        if (best.lat != null) placeArgs.lat = best.lat;
        if (best.lng != null) placeArgs.lng = best.lng;
        if (best.address) placeArgs.address = best.address;
        if (best.google_place_id) placeArgs.google_place_id = best.google_place_id;
        if (best.google_ftid) placeArgs.google_ftid = best.google_ftid;
        if (best.osm_id) placeArgs.osm_id = best.osm_id;
        const createdPlace = await mcpTool(sessionId, 'create_place', placeArgs);
        placeId = createdPlace.place ? createdPlace.place.id : createdPlace.id;
      } else {
        placeSearchNote = 'No place match found for "' + searchQuery + '"';
      }
    }
    if (placeId) {
      const accomArgs = {
        tripId: tripId,
        place_id: placeId,
        start_day_id: startDayId,
        end_day_id: endDayId,
      };
      if (ex.confirmation_code) accomArgs.confirmation = ex.confirmation_code;
      if (ex.notes) accomArgs.notes = ex.notes;
      createdBooking = await mcpTool(sessionId, 'create_accommodation', accomArgs);
    } else {
      const args = {
        tripId: tripId,
        type: 'hotel',
        title: (ex.provider_name || 'Hotel') + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
      };
      if (startDayId) args.day_id = startDayId;
      if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
      if (ex.notes) args.notes = ex.notes;
      if (placeSearchNote) args.notes = (args.notes ? args.notes + ' - ' : '') + placeSearchNote;
      createdBooking = await mcpTool(sessionId, 'create_reservation', args);
    }
  } else {
    const typeMap = { lodging: 'hotel', rental_car: 'other', restaurant: 'restaurant', activity: 'activity', general: 'other' };
    const args = {
      tripId: tripId,
      type: typeMap[ex.booking_type] || 'other',
      title: (ex.provider_name || ex.booking_type || 'Booking') + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
    };
    if (startDayId) args.day_id = startDayId;
    if (ex.start_datetime) args.reservation_time = ex.start_datetime;
    if (ex.end_datetime) args.reservation_end_time = ex.end_datetime;
    if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
    if (ex.notes) args.notes = ex.notes;
    createdBooking = await mcpTool(sessionId, 'create_reservation', args);
  }
}

return [
  {
    json: Object.assign({}, item, {
      trekTripId: tripId,
      trekCreatedNewTrip: createdNewTrip,
      trekIsDuplicate: isDuplicate,
      trekCreatedBooking: createdBooking,
      trekPlaceSearchNote: placeSearchNote,
    }),
  },
];
